CREATE TABLE IF NOT EXISTS users (
 id BIGSERIAL PRIMARY KEY, provider VARCHAR(20) NOT NULL DEFAULT 'google' CHECK(provider='google'),
 provider_id VARCHAR(150) NOT NULL, email VARCHAR(320) UNIQUE, display_name VARCHAR(120) NOT NULL,
 avatar_url TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','blocked')),
 role VARCHAR(20) NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 UNIQUE(provider,provider_id)
);
CREATE TABLE IF NOT EXISTS titles (
 id BIGSERIAL PRIMARY KEY,title VARCHAR(180) NOT NULL,synopsis TEXT NOT NULL DEFAULT '',
 kind VARCHAR(20) NOT NULL CHECK(kind IN ('movie','series')),category VARCHAR(80) NOT NULL DEFAULT 'Geral',
 poster_url TEXT NOT NULL DEFAULT '',banner_url TEXT NOT NULL DEFAULT '',playback_url TEXT NOT NULL DEFAULT '',
 year INTEGER,age_rating VARCHAR(20) DEFAULT 'Livre',duration_minutes INTEGER,
 featured BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS seasons(id BIGSERIAL PRIMARY KEY,title_id BIGINT NOT NULL REFERENCES titles(id) ON DELETE CASCADE,season_number INTEGER NOT NULL,title VARCHAR(120),active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(title_id,season_number));
CREATE TABLE IF NOT EXISTS episodes(id BIGSERIAL PRIMARY KEY,season_id BIGINT NOT NULL REFERENCES seasons(id) ON DELETE CASCADE,episode_number INTEGER NOT NULL,title VARCHAR(180) NOT NULL,synopsis TEXT DEFAULT '',duration_minutes INTEGER,thumbnail_url TEXT DEFAULT '',playback_url TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(season_id,episode_number));
CREATE TABLE IF NOT EXISTS reviews(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title_id BIGINT NOT NULL REFERENCES titles(id) ON DELETE CASCADE,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(1500) DEFAULT '',moderated BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,title_id));
CREATE TABLE IF NOT EXISTS watch_progress(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title_id BIGINT NOT NULL REFERENCES titles(id) ON DELETE CASCADE,seconds INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(user_id,title_id));
CREATE TABLE IF NOT EXISTS user_lists(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title_id BIGINT NOT NULL REFERENCES titles(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(user_id,title_id));
CREATE TABLE IF NOT EXISTS user_sessions(sid VARCHAR NOT NULL PRIMARY KEY,sess JSON NOT NULL,expire TIMESTAMP(6) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_titles_active_kind ON titles(active,kind,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_progress_user ON watch_progress(user_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_reviews_title ON reviews(title_id,moderated,created_at DESC);
ALTER TABLE titles ADD COLUMN IF NOT EXISTS duration_minutes INTEGER;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url TEXT;
CREATE TABLE IF NOT EXISTS banners(id BIGSERIAL PRIMARY KEY,title VARCHAR(180) NOT NULL,image_url TEXT NOT NULL,link_title_id BIGINT REFERENCES titles(id) ON DELETE SET NULL,active BOOLEAN NOT NULL DEFAULT TRUE,position INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
